package com.xcloud.metadata.inceptor;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/**
 * Build stamp of the running jar ({@code META-INF/build-info.properties}, generated by the
 * {@code build-info} goal of the Spring Boot Maven plugin).
 *
 * <p>Intranet upgrades repeatedly hit the question "did the new jar actually get deployed?"; the
 * start up log, {@code /api/catalog/status} and the UI all print this stamp so the running build can
 * be compared with the one that was just built. Empty when running from an IDE or a plain test run.
 */
public final class BuildInfo {

    private static final Properties PROPERTIES = load();

    private BuildInfo() {
    }

    public static String version() {
        return PROPERTIES.getProperty("build.version", "");
    }

    /** ISO-8601 instant of the build, or an empty string when the stamp is missing. */
    public static String builtAt() {
        return PROPERTIES.getProperty("build.time", "");
    }

    private static Properties load() {
        Properties properties = new Properties();
        try (InputStream stream = BuildInfo.class.getResourceAsStream("/META-INF/build-info.properties")) {
            if (stream != null) {
                properties.load(stream);
            }
        } catch (IOException ignored) {
            // A missing stamp must never break the application.
        }
        return properties;
    }
}
